CREATE TABLE IF NOT EXISTS companies (id BIGSERIAL PRIMARY KEY, legal_name TEXT NOT NULL, rut TEXT UNIQUE, trade_name TEXT, email TEXT, phone TEXT, address TEXT, commune TEXT, region TEXT, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles (id BIGSERIAL PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS permissions (id BIGSERIAL PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, module TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id BIGINT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL, role_id BIGINT REFERENCES roles(id) ON DELETE SET NULL, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT, phone TEXT, active BOOLEAN NOT NULL DEFAULT true, last_login_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clients (id BIGSERIAL PRIMARY KEY, company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL, rut TEXT, name TEXT NOT NULL, contact_name TEXT, email TEXT, phone TEXT, address TEXT, commune TEXT, region TEXT, payment_terms_days INTEGER NOT NULL DEFAULT 30, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client_locations (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, address TEXT, commune TEXT, region TEXT, lat NUMERIC, lng NUMERIC, active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS vehicle_documents (id BIGSERIAL PRIMARY KEY, truck_id INTEGER REFERENCES trucks(id) ON DELETE CASCADE, document_type TEXT NOT NULL, document_number TEXT, issued_at DATE, expires_at DATE, status TEXT NOT NULL DEFAULT 'Vigente', file_url TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS driver_documents (id BIGSERIAL PRIMARY KEY, driver_id INTEGER REFERENCES drivers(id) ON DELETE CASCADE, document_type TEXT NOT NULL, document_number TEXT, issued_at DATE, expires_at DATE, status TEXT NOT NULL DEFAULT 'Vigente', file_url TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trips (id BIGSERIAL PRIMARY KEY, company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL, trip_number TEXT UNIQUE NOT NULL, truck_id INTEGER REFERENCES trucks(id) ON DELETE SET NULL, driver_id INTEGER REFERENCES drivers(id) ON DELETE SET NULL, client_id BIGINT REFERENCES clients(id) ON DELETE SET NULL, origin TEXT NOT NULL, destination TEXT NOT NULL, planned_departure TIMESTAMPTZ, planned_arrival TIMESTAMPTZ, actual_departure TIMESTAMPTZ, actual_arrival TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'Planificado', distance_km NUMERIC DEFAULT 0, revenue_clp BIGINT DEFAULT 0, fuel_cost_clp BIGINT DEFAULT 0, toll_cost_clp BIGINT DEFAULT 0, maintenance_cost_clp BIGINT DEFAULT 0, other_cost_clp BIGINT DEFAULT 0, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trip_events (id BIGSERIAL PRIMARY KEY, trip_id BIGINT NOT NULL REFERENCES trips(id) ON DELETE CASCADE, event_type TEXT NOT NULL, event_time TIMESTAMPTZ NOT NULL DEFAULT now(), lat NUMERIC, lng NUMERIC, notes TEXT, created_by BIGINT REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS trip_loads (id BIGSERIAL PRIMARY KEY, trip_id BIGINT NOT NULL REFERENCES trips(id) ON DELETE CASCADE, client_id BIGINT REFERENCES clients(id) ON DELETE SET NULL, guide TEXT, cargo TEXT NOT NULL, weight_kg NUMERIC DEFAULT 0, volume_m3 NUMERIC DEFAULT 0, value_clp BIGINT DEFAULT 0, origin TEXT, destination TEXT, status TEXT NOT NULL DEFAULT 'Planificada', delivered_at TIMESTAMPTZ, recipient_name TEXT, recipient_rut TEXT, delivery_notes TEXT, delivery_signature_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vehicle_checklists (id BIGSERIAL PRIMARY KEY, truck_id INTEGER NOT NULL REFERENCES trucks(id) ON DELETE CASCADE, driver_id INTEGER REFERENCES drivers(id) ON DELETE SET NULL, trip_id BIGINT REFERENCES trips(id) ON DELETE SET NULL, checklist_type TEXT NOT NULL DEFAULT 'Preoperacional', status TEXT NOT NULL DEFAULT 'Pendiente', items JSONB NOT NULL DEFAULT '[]'::jsonb, observations TEXT, completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT, before_data JSONB, after_data JSONB, ip TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE trucks ADD COLUMN IF NOT EXISTS company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL;
ALTER TABLE drivers ADD COLUMN IF NOT EXISTS company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL;
ALTER TABLE routes ADD COLUMN IF NOT EXISTS company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL;
ALTER TABLE loads ADD COLUMN IF NOT EXISTS company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL;
ALTER TABLE maintenance ADD COLUMN IF NOT EXISTS company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL;
ALTER TABLE fuel ADD COLUMN IF NOT EXISTS company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL;
ALTER TABLE alerts ADD COLUMN IF NOT EXISTS company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS idx_trucks_company ON trucks(company_id);
CREATE INDEX IF NOT EXISTS idx_drivers_company ON drivers(company_id);
CREATE INDEX IF NOT EXISTS idx_clients_company ON clients(company_id);
CREATE INDEX IF NOT EXISTS idx_trips_company_status ON trips(company_id,status);
CREATE INDEX IF NOT EXISTS idx_vehicle_documents_expiry ON vehicle_documents(expires_at);
CREATE INDEX IF NOT EXISTS idx_driver_documents_expiry ON driver_documents(expires_at);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
INSERT INTO roles(code,name,description) VALUES ('admin','Administrador','Acceso completo al sistema'),('manager','Gerente','Gestión y reportes'),('operations','Operaciones','Despacho, viajes, cargas y seguimiento'),('maintenance','Mantención','Mantenimiento y documentación técnica'),('driver','Conductor','Operación de viajes y checklist'),('viewer','Consulta','Solo lectura') ON CONFLICT(code) DO NOTHING;
INSERT INTO permissions(code,name,module) VALUES ('dashboard.read','Ver dashboard','dashboard'),('fleet.manage','Gestionar flota','fleet'),('drivers.manage','Gestionar conductores','drivers'),('clients.manage','Gestionar clientes','clients'),('trips.manage','Gestionar viajes','operations'),('loads.manage','Gestionar cargas','operations'),('gps.read','Ver GPS','gps'),('maintenance.manage','Gestionar mantenciones','maintenance'),('fuel.manage','Gestionar combustible','fuel'),('documents.manage','Gestionar documentos','documents'),('reports.read','Ver reportes','reports'),('users.manage','Gestionar usuarios','admin'),('audit.read','Ver auditoría','admin') ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='admin' ON CONFLICT DO NOTHING;
